import java.util.*;
import java.io.*;

public class Main {
    static long[][] multiply(long[][] A, long[][] B) {
        // Write your solution here
        return new long[0][0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int p = (int) in.nval;
        long[][] A = new long[n][m];
        long[][] B = new long[m][p];
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) { in.nextToken(); A[i][j] = (long) in.nval; }
        for (int i = 0; i < m; i++) for (int j = 0; j < p; j++) { in.nextToken(); B[i][j] = (long) in.nval; }
        long[][] C = multiply(A, B);
        StringBuilder sb = new StringBuilder();
        for (long[] row : C) {
            for (int j = 0; j < row.length; j++) sb.append(row[j]).append(j + 1 < row.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
